1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { isNavigable, seaMap } from "@pirate-sea-race/content";
3	import { JournalMessageType, journalMessageSchema, MAX_BUY_RUMOR_PER_SECOND, type JournalMessage } from "@pirate-sea-race/protocol";
4	import { startGameServer, type MatchRoom, type RunningGameServer } from "@pirate-sea-race/server";
5	import { objectiveRules } from "@pirate-sea-race/simulation/objectives";
6	import { HeadlessClient, ImpairmentProxy, sleep, type Movement } from "@pirate-sea-race/test-tools";
7	import { GUEST_SEAT, HOST_SEAT, placePair, tuned } from "./rubbingsSetup.js";
8	import { collectAt, containsText, HOLD_E, HUB_X, OPEN_ROW, openWater, playersAt, roomOf, startThroughLobby, tracker, until, EAST, type Seat } from "./seaDuelSetup.js";
9	
10	/**
11	 * §3 and §11's intel through the real room: start rumors, fresh and replacement leads, the journal log in each player's
12	 * own status, and targeted rumor purchases, read from what the headless clients received (and, for §16, from their raw
13	 * frames). Every island seals one Sun and one Moon here (test-only), so collecting an island's Sun leaves a rumor about
14	 * it stale. Players start with 40 gold (test-only), so one rumor (25) is affordable and a second is not. The rooms check
15	 * `checkLedger` (the gold identity among it) and their own invariant after every world tick (`tracker`). Cases that
16	 * need one exact tick line requests up with the room's test hooks (`testBuyRumor`, `stepWorldTicks`) while the clock is
17	 * paused.
18	 */
19	const LAYOUT = [
20	  ["sun", "moon"],
21	  ["sun", "moon"],
22	  ["sun", "moon"],
23	  ["sun", "moon"],
24	];
25	const GOLD = 40;
26	const PRICE = objectiveRules.rumorPrice;
27	let server: RunningGameServer;
28	let endpoint: string;
29	
30	beforeAll(async () => {
31	  const matchTuning = tuned({
32	    sourceLayout: LAYOUT,
33	    objectives: { ...objectiveRules, collectTicks: 20, cacheClaimTicks: 20, startingGold: GOLD },
34	    testHooks: true,
35	  });
36	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
37	  endpoint = `http://127.0.0.1:${server.port}`;
38	});
39	
40	afterAll(async () => {
41	  await server.close();
42	});
43	
44	/** Open water in a row south of the hub, one seat per player, out of every dock's way. */
45	const seat = (index: number): Seat => ({ tileX: HUB_X - 8 + index * 4, tileY: OPEN_ROW, heading: EAST });
46	const dockOf = (island: number, which = 0) => seaMap.docks.filter((dock) => dock.island === island)[which]!;
47	
48	/** Open water `distance` tiles from a dock, in a straight clear line from it, facing the dock (a grapple's aim). */
49	function seatOff(dock: { tileX: number; tileY: number }, distance: number): Seat {
50	  for (const [dx, dy] of [
51	    [-1, 0],
52	    [1, 0],
53	    [0, -1],
54	    [0, 1],
55	  ] as const) {
56	    const at = { tileX: dock.tileX + dx * distance, tileY: dock.tileY + dy * distance, heading: 0 };
57	    if (!isNavigable(seaMap, at.tileX, at.tileY) || !openWater(at, { ...dock, heading: 0 })) continue;
58	    return { ...at, heading: (Math.round((Math.atan2(-dy, -dx) / (2 * Math.PI)) * 64) + 64) % 64 };
59	  }
60	  throw new Error(`no open water ${distance} tiles off dock ${dock.tileX},${dock.tileY}`);
61	}
62	
63	async function moor(client: HeadlessClient, dock: { id: number; tileX: number; tileY: number }): Promise<void> {
64	  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
65	  await client.holdUntil(HOLD_E, () => client.ship()?.dock === dock.id, 5000);
66	}
67	
68	/** The player's start rumor, once it arrived. */
69	async function startRumor(client: HeadlessClient): Promise<Extract<JournalMessage, { kind: "rumor" }>> {
70	  await client.waitFor(() => client.leads.some((lead) => lead.kind === "rumor" && lead.reason === "start"));
71	  return client.leads.find((lead) => lead.kind === "rumor" && lead.reason === "start") as Extract<JournalMessage, { kind: "rumor" }>;
72	}
73	
74	/** The ledger's purchases for a player. */
75	const purchasesOf = (room: MatchRoom, id: string) => room.ledgerState.requests.filter((outcome) => outcome.kind === "purchase" && outcome.playerId === id);
76	const goldOf = (room: MatchRoom, id: string) => room.ledgerState.players.find((player) => player.id === id)!.gold;
77	
78	/** Holds the room's clock after the current world tick. */
79	async function pause(room: MatchRoom): Promise<void> {
80	  room.pauseAfterTick(room.matchState.worldTick);
81	  await until(() => room.worldPaused, 2000, "the pause");
82	}
83	
84	/** The targeted leads a player received (rumors, or sighting entries, bought), each once (a replay resends its lead). */
85	const targetedLeads = (client: HeadlessClient) =>
86	  [...new Map(client.leads.map((lead) => [JSON.stringify(lead), lead])).values()].flatMap((lead) =>
87	    lead.kind === "rumor" && lead.reason === "targeted" ? [lead.type] : lead.kind === "carrier-sighting" ? lead.sightings.filter((each) => each.reason === "targeted").map((each) => each.type) : [],
88	  );
89	
90	describe.concurrent("rumors and the journal (§3, §11)", () => {
91	  it("gives every player a start rumor at control start: an island with a sealed source of a type they lack, never a carrier; the journal and the offers show it", async ({ onTestFinished }) => {
92	    const track = tracker(onTestFinished);
93	    const clients = await playersAt(endpoint, [seat(0), seat(1), seat(2)], track);
94	    const room = roomOf(clients[0]!);
95	    const controlStart = room.flowState.controlStartTick!;
96	    for (const client of clients) {
97	      const rumor = await startRumor(client);
98	      expect(rumor.tick).toBe(controlStart);
99	      expect(rumor.entry).toBe(1);
100	      // No cache exists yet, so it names an island, where a source of that type is still sealed.
101	      expect(rumor.target.kind).toBe("island");
102	      const island = rumor.target.kind === "island" ? rumor.target.island : -1;
103	      expect(rumor.target.name).toBe(seaMap.islands[island]!.name);
104	      const sealed = room.ledgerState.rubbings.filter((rubbing) => rubbing.location.kind === "source" && rubbing.type === rumor.type);
105	      expect(sealed.some((rubbing) => rubbing.location.kind === "source" && room.ledgerState.sources.find((source) => source.id === (rubbing.location as { sourceId: string }).sourceId)!.island === island)).toBe(true);
106	      expect(client.rubbings()).not.toContain(rumor.type);
107	      // One lead each, and never a carrier.
108	      expect(client.leads).toHaveLength(1);
109	      expect(client.leads.some((lead) => lead.kind === "carrier-sighting")).toBe(false);
110	      // The journal in the player's own status says the same; both types can still be bought.
111	      await client.waitFor(() => client.journal().length === 1);
112	      expect(client.journal()).toEqual([
113	        { n: 1, kind: "island", type: rumor.type, target: rumor.target.name, island, sector: -1, reason: "start", tick: controlStart, seenTick: 0, status: "active", replacedBy: 0 },
114	      ]);
115	      await client.waitFor(() => client.rumorOffers().length === 2);
116	      expect(client.rumorOffers()).toEqual([
117	        { type: "sun", offer: "available" },
118	        { type: "moon", offer: "available" },
119	      ]);
120	    }
121	    // Known islands: the ones in sight or moored at, with their ruin as last seen (open here) and not solved by them.
122	    const [first] = clients as [HeadlessClient];
123	    await moor(first, dockOf(3));
124	    await first.waitFor(() => first.knownIslands().some((known) => known.island === 3));
125	    expect(first.knownIslands().find((known) => known.island === 3)).toEqual({ island: 3, unlocked: true, solved: false });
126	    // Listed in island order, whatever order they were sighted in.
127	    await moor(first, dockOf(0));
128	    await first.waitFor(() => first.knownIslands().length === 2);
129	    expect(first.knownIslands().map((known) => known.island)).toEqual([0, 3]);
130	  }, 30_000);
131	
132	  it("replaces a journal rumor whose source is collected, and gives a player who loses a type in a settled theft a fresh rumor; entering the duel is no loss", async ({ onTestFinished }) => {
133	    const track = tracker(onTestFinished);
134	    // The victim never readies its arena: it loses the duel by forfeit.
135	    const [thief, victim, collector] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT, seat(0)], track, { clients: [{}, { autoReady: false }, {}] })) as [HeadlessClient, HeadlessClient, HeadlessClient];
136	    const room = roomOf(victim);
137	    const start = await startRumor(victim);
138	    const island = start.target.kind === "island" ? start.target.island : -1;
139	
140	    // Another player collects that island's source of the rumor's type: the rumor goes stale and is replaced.
141	    await collectAt(collector, endpoint, dockOf(island), start.type);
142	    await victim.waitFor(() => victim.leads.some((lead) => lead.kind === "rumor-stale"));
143	    expect(victim.leads.find((lead) => lead.kind === "rumor-stale")).toMatchObject({ entry: 1, type: start.type });
144	    await victim.waitFor(() => victim.leads.some((lead) => lead.kind === "rumor" && lead.reason === "replacement"));
145	    const replacement = victim.leads.find((lead) => lead.kind === "rumor" && lead.reason === "replacement") as Extract<JournalMessage, { kind: "rumor" }>;
146	    expect(replacement).toMatchObject({ type: start.type, entry: 2 });
147	    expect(replacement.target).not.toEqual(start.target);
148	    await victim.waitFor(() => victim.journal().length === 2);
149	    expect(victim.journal().map(({ n, status, replacedBy, reason }) => ({ n, status, replacedBy, reason }))).toEqual([
150	      { n: 1, status: "stale", replacedBy: 2, reason: "start" },
151	      { n: 2, status: "active", replacedBy: 0, reason: "replacement" },
152	    ]);
153	
154	    // The victim collects a Sun; the thief grapples it and takes it.
155	    const other = [0, 1, 2, 3].find((each) => each !== island)!;
156	    await collectAt(victim, endpoint, dockOf(other, 1), "sun");
157	    const before = victim.leads.length;
158	    await placePair(endpoint, thief, victim);
159	    thief.tapGrapple();
160	    await victim.waitFor(() => victim.fighter.phase === "countdown", 5000);
161	    // Reserved in the duel: still held, so no loss and no fresh lead.
162	    await sleep(300);
163	    expect(room.ledgerState.rubbings.some((rubbing) => rubbing.location.kind === "duel" && rubbing.location.playerId === victim.sessionId)).toBe(true);
164	    expect(victim.leads.slice(before).some((lead) => lead.kind !== "rumor-resolved")).toBe(false);
165	    await thief.waitFor(() => thief.objectives()?.theftOptions.join(",") === "sun", 10_000);
166	    thief.chooseTheft("sun");
167	    await victim.waitFor(() => !victim.rubbings().includes("sun"), 5000);
168	    // The loser's free fresh lead about the Sun it lost (a sealed Sun is still on the map, so a rumor).
169	    await victim.waitFor(() => victim.leads.some((lead) => lead.kind === "rumor" && lead.reason === "fresh"), 3000);
170	    const fresh = victim.leads.find((lead) => lead.kind === "rumor" && lead.reason === "fresh")!;
171	    // The winner's choice arrived between ticks: the intel step saw the loss on the next one.
172	    const settledAt = room.ledgerState.duels.at(-1)!.settlement!.tick;
173	    expect(fresh).toMatchObject({ type: "sun", tick: settledAt + 1 });
174	    expect(goldOf(room, victim.sessionId)).toBeLessThan(GOLD);
175	    expect(purchasesOf(room, victim.sessionId)).toEqual([]);
176	  }, 45_000);
177	});
178	
179	describe.concurrent("targeted rumors (§11)", () => {
180	  it("sells a rumor for 25 gold at a dock, replays a retried id without charging again, refuses too little gold and replays the refusal", async ({ onTestFinished }) => {
181	    const track = tracker(onTestFinished);
182	    const [buyer] = (await playersAt(endpoint, [seat(0)], track)) as [HeadlessClient];
183	    const room = roomOf(buyer);
184	    await startRumor(buyer);
185	    await moor(buyer, dockOf(0));
186	    await buyer.waitFor(() => buyer.rumorOffers().some((offer) => offer.type === "moon" && offer.offer === "available"));
187	    const id = buyer.buyRumor("moon");
188	    await buyer.waitFor(() => buyer.rumorAnswers(id).length === 1);
189	    expect(buyer.rumorAnswers(id)).toEqual([{ requestId: id, type: "moon", outcome: "bought", price: PRICE, replayed: false }]);
190	    const bought = buyer.leads.filter((lead) => lead.kind === "rumor" && lead.reason === "targeted");
191	    expect(bought).toEqual([expect.objectContaining({ type: "moon" })]);
192	    await buyer.waitFor(() => buyer.gold() === GOLD - PRICE);
193	    expect(purchasesOf(room, buyer.sessionId)).toEqual([expect.objectContaining({ requestId: id, item: "rumor", price: PRICE })]);
194	    await buyer.waitFor(() => buyer.journal().some((entry) => entry.reason === "targeted"));
195	
196	    // The retry: the same answer and the same lead again, marked replayed, nothing charged (15 gold now, under the price).
197	    const leadsBefore = buyer.leads.length;
198	    buyer.buyRumor("moon", id);
199	    await buyer.waitFor(() => buyer.rumorAnswers(id).length === 2);
200	    expect(buyer.rumorAnswers(id)[1]).toEqual({ requestId: id, type: "moon", outcome: "bought", price: PRICE, replayed: true });
201	    expect(buyer.leads.slice(leadsBefore)).toEqual(bought);
202	    expect(goldOf(room, buyer.sessionId)).toBe(GOLD - PRICE);
203	    expect(purchasesOf(room, buyer.sessionId)).toHaveLength(1);
204	    // The journal did not log the resent lead again.
205	    expect(buyer.journal().filter((entry) => entry.reason === "targeted")).toHaveLength(1);
206	
207	    // Too little gold: refused, nothing charged; its retry gets the same refusal.
208	    const short = buyer.buyRumor("sun");
209	    await buyer.waitFor(() => buyer.rumorAnswers(short).length === 1);
210	    expect(buyer.rumorAnswers(short)[0]).toMatchObject({ outcome: "refused", reason: "insufficient-gold", replayed: false });
211	    buyer.buyRumor("sun", short);
212	    await buyer.waitFor(() => buyer.rumorAnswers(short).length === 2);
213	    expect(buyer.rumorAnswers(short)[1]).toMatchObject({ outcome: "refused", reason: "insufficient-gold", replayed: true });
214	    expect(goldOf(room, buyer.sessionId)).toBe(GOLD - PRICE);
215	    expect(purchasesOf(room, buyer.sessionId)).toHaveLength(1);
216	    // The ledger never saw the refusal: the room refused it before any charge.
217	    expect(room.ledgerState.requests.filter((outcome) => outcome.playerId === buyer.sessionId)).toHaveLength(1);
218	  }, 30_000);
219	
220	  it("resolves requests on exact ticks: one per player per tick, merged retries, a busy third, independent ids per player, no charge without a lead, and a cast-off refusal", async ({ onTestFinished }) => {
221	    const track = tracker(onTestFinished);
222	    const [twice, merger, same1, same2, holder] = (await playersAt(endpoint, [seat(0), seat(1), seat(2), seat(3), seat(4)], track)) as HeadlessClient[] as [
223	      HeadlessClient,
224	      HeadlessClient,
225	      HeadlessClient,
226	      HeadlessClient,
227	      HeadlessClient,
228	    ];
229	    const room = roomOf(twice);
230	    // The holder takes a Sun: a rumor about the Sun has nothing to sell it, and its offers leave the Sun out.
231	    await collectAt(holder, endpoint, dockOf(0, 0), "sun");
232	    await holder.waitFor(() => holder.rumorOffers().length === 1);
233	    expect(holder.rumorOffers()).toEqual([{ type: "moon", offer: "available" }]);
234	    await moor(twice, dockOf(0, 1));
235	    await moor(merger, dockOf(1, 0));
236	    await moor(same1, dockOf(1, 1));
237	    await moor(same2, dockOf(2, 0));
238	    // The test hook steps only a paused clock.
239	    expect(() => room.stepWorldTicks(1)).toThrow("needs the world paused");
240	    await pause(room);
241	    const tick = room.matchState.worldTick;
242	    // Two types in one tick from 40 gold; a pending id twice, a second id and a busy third; one id for two players;
243	    // and a type the player holds.
244	    room.testBuyRumor(twice.sessionId, { requestId: "a", type: "sun" });
245	    room.testBuyRumor(twice.sessionId, { requestId: "b", type: "moon" });
246	    room.testBuyRumor(merger.sessionId, { requestId: "m", type: "moon" });
247	    room.testBuyRumor(merger.sessionId, { requestId: "m", type: "moon" });
248	    room.testBuyRumor(merger.sessionId, { requestId: "n", type: "sun" });
249	    room.testBuyRumor(merger.sessionId, { requestId: "o", type: "sun" });
250	    room.testBuyRumor(same1.sessionId, { requestId: "same", type: "moon" });
251	    room.testBuyRumor(same2.sessionId, { requestId: "same", type: "moon" });
252	    room.testBuyRumor(holder.sessionId, { requestId: "held", type: "sun" });
253	    expect(room.pendingRumors(merger.sessionId)).toBe(2);
254	    await merger.waitFor(() => merger.rumorAnswers("o").length === 1);
255	    expect(merger.rumorAnswers("o")[0]).toMatchObject({ outcome: "refused", reason: "busy" });
256	
257	    room.stepWorldTicks(1);
258	    // The first of two requests is decided and charged on this tick; the second waits.
259	    expect(purchasesOf(room, twice.sessionId)).toEqual([expect.objectContaining({ requestId: "a", tick: tick + 1 })]);
260	    expect(room.pendingRumors(twice.sessionId)).toBe(1);
261	    expect(purchasesOf(room, merger.sessionId)).toEqual([expect.objectContaining({ requestId: "m" })]);
262	    // Two players' requests under one client id are independent: both bought, each charged once, under namespaced intel ids.
263	    for (const client of [same1, same2]) expect(purchasesOf(room, client.sessionId)).toEqual([expect.objectContaining({ requestId: "same" })]);
264	    expect(room.intelState!.requestIds).toEqual(expect.arrayContaining([`${same1.sessionId}:same`, `${same2.sessionId}:same`]));
265	    // A type the player holds: refused `none` before the intel step, which never saw it.
266	    expect(room.intelState!.requestIds).not.toContain(`${holder.sessionId}:held`);
267	    expect(purchasesOf(room, holder.sessionId)).toEqual([]);
268	
269	    room.stepWorldTicks(1);
270	    // The second request of the first player, on the next tick: 15 gold now, refused without a charge.
271	    expect(purchasesOf(room, twice.sessionId)).toHaveLength(1);
272	    expect(room.pendingRumors(twice.sessionId)).toBe(0);
273	    expect(room.intelState!.requestIds).not.toContain(`${twice.sessionId}:b`);
274	    expect(goldOf(room, twice.sessionId)).toBe(GOLD - PRICE);
275	    expect(room.invariantViolations).toEqual([]);
276	
277	    // A request queued at a dock and processed after the ship cast off: refused, nothing charged.
278	    const castOff: Movement = { moveX: 0, moveY: -1 };
279	    twice.sendInput(castOff);
280	    await sleep(200);
281	    room.testBuyRumor(twice.sessionId, { requestId: "c", type: "moon" });
282	    room.stepWorldTicks(1);
283	    expect(room.matchState.ships.find((ship) => ship.id === twice.sessionId)!.dock).toBe(-1);
284	    room.resumeWorld();
285	    twice.sendInput({ moveX: 0, moveY: 0 });
286	
287	    await twice.waitFor(() => twice.rumorAnswers("c").length === 1 && twice.rumorAnswers("b").length === 1);
288	    expect(twice.rumorAnswers("a")).toEqual([expect.objectContaining({ outcome: "bought", replayed: false })]);
289	    expect(twice.rumorAnswers("b")).toEqual([expect.objectContaining({ outcome: "refused", reason: "insufficient-gold" })]);
290	    expect(twice.rumorAnswers("c")).toEqual([expect.objectContaining({ outcome: "refused", reason: "not-at-dock" })]);
291	    // The merged retry was answered once, with the one decision.
292	    await merger.waitFor(() => merger.rumorAnswers("n").length === 1);
293	    expect(merger.rumorAnswers("m")).toEqual([expect.objectContaining({ outcome: "bought" })]);
294	    expect(merger.rumorAnswers("n")).toEqual([expect.objectContaining({ outcome: "refused", reason: "insufficient-gold" })]);
295	    await holder.waitFor(() => holder.rumorAnswers("held").length === 1);
296	    expect(holder.rumorAnswers("held")[0]).toMatchObject({ outcome: "refused", reason: "none" });
297	    for (const client of [twice, merger, same1, same2]) {
298	      await client.waitFor(() => client.gold() === GOLD - PRICE);
299	      expect(targetedLeads(client)).toHaveLength(1);
300	    }
301	    expect(goldOf(room, holder.sessionId)).toBe(GOLD);
302	  }, 45_000);
303	
304	  it("refuses without charge a request the intel step answers with nothing on its tick: a stale rumor's free replacement covers it", async ({ onTestFinished }) => {
305	    const track = tracker(onTestFinished);
306	    const [buyer, collector] = (await playersAt(endpoint, [seat(0), seat(2)], track)) as [HeadlessClient, HeadlessClient];
307	    const room = roomOf(buyer);
308	    const start = await startRumor(buyer);
309	    const island = start.target.kind === "island" ? start.target.island : -1;
310	    // The buyer at another island's dock; the collector at the rumor's island, about to take its source of that type.
311	    await moor(buyer, dockOf((island + 1) % 4));
312	    const dock = dockOf(island);
313	    await collector.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
314	    if (start.type === "moon") await collectAt(collector, endpoint, dock, "sun");
315	    let done = false;
316	    const holding = collector.holdUntil(HOLD_E, () => done, 15_000);
317	    await until(() => room.ledgerState.players.find((player) => player.id === collector.sessionId)?.channel?.kind === "collect", 5000, "the collection");
318	    const channel = room.ledgerState.players.find((player) => player.id === collector.sessionId)!.channel!;
319	    // Held just before the tick the collection completes on.
320	    room.pauseAfterTick(channel.startTick + room.ledgerState.rules.collectTicks - 1);
321	    await until(() => room.worldPaused, 3000, "the pause");
322	    room.testBuyRumor(buyer.sessionId, { requestId: "late", type: start.type });
323	    room.stepWorldTicks(1);
324	    // On that tick the source went to the collector: the buyer's rumor went stale, its free replacement gives the type,
325	    // and the purchase was answered `covered` by the intel step, with no charge.
326	    expect(room.ledgerState.rubbings.some((rubbing) => rubbing.type === start.type && rubbing.location.kind === "player" && rubbing.location.playerId === collector.sessionId)).toBe(true);
327	    expect(room.intelState!.requestIds).toContain(`${buyer.sessionId}:late`);
328	    expect(purchasesOf(room, buyer.sessionId)).toEqual([]);
329	    expect(goldOf(room, buyer.sessionId)).toBe(GOLD);
330	    room.resumeWorld();
331	    done = true;
332	    await holding;
333	    await buyer.waitFor(() => buyer.rumorAnswers("late").length === 1);
334	    expect(buyer.rumorAnswers("late")[0]).toMatchObject({ outcome: "refused", reason: "covered" });
335	    expect(buyer.leads.some((lead) => lead.kind === "rumor" && lead.reason === "replacement" && lead.type === start.type)).toBe(true);
336	    expect(targetedLeads(buyer)).toEqual([]);
337	  }, 30_000);
338	
339	  it("refuses a purchase during a duel and while waiting to respawn, and replays a bought id meanwhile", async ({ onTestFinished }) => {
340	    const track = tracker(onTestFinished);
341	    // The buyer never readies: it loses by forfeit and waits to respawn.
342	    const [buyer, attacker] = (await playersAt(endpoint, [seat(0), seat(3)], track, { clients: [{ autoReady: false }, {}] })) as [HeadlessClient, HeadlessClient];
343	    const room = roomOf(buyer);
344	    await startRumor(buyer);
345	    const dock = dockOf(1, 1);
346	    await moor(buyer, dock);
347	    const id = buyer.buyRumor("sun");
