1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import type { JournalMessage } from "@pirate-sea-race/protocol";
4	import { DEFAULT_MATCH_TUNING, startGameServer, testTimingsTuning, type RunningGameServer } from "@pirate-sea-race/server";
5	import { createIntelConfig, sectorOf } from "@pirate-sea-race/simulation/intel";
6	import { objectiveRules } from "@pirate-sea-race/simulation/objectives";
7	import type { HeadlessClient } from "@pirate-sea-race/test-tools";
8	import { tuned } from "./rubbingsSetup.js";
9	import { collectAt, dockFor, EAST, HOLD_E, HUB_X, OPEN_ROW, playersAt, roomOf, tracker, until, type Seat } from "./seaDuelSetup.js";
10	
11	/**
12	 * §3 and §11's carrier sightings through the real room, with test-only short timings: carrier snapshots every second
13	 * (`carrierInterval`, which is also the sighting delay), the sector reveal at 5 s and the carrier reveal at 20 s. The
14	 * slice has four copies of each type and a player holds one of each at most, so four players carry every Sun and a
15	 * fifth, the seeker, lacks it: its lead about the Sun can only be a sighting, delayed by an interval, one per snapshot.
16	 */
17	const INTERVAL = 20;
18	const SECTORS = 100;
19	const CARRIERS = 400;
20	let server: RunningGameServer;
21	let endpoint: string;
22	
23	beforeAll(async () => {
24	  const intel = testTimingsTuning({ sectors: SECTORS, carriers: CARRIERS, carrierInterval: INTERVAL }, DEFAULT_MATCH_TUNING).intel!;
25	  const matchTuning = tuned({ objectives: { ...objectiveRules, collectTicks: 20, cacheClaimTicks: 20 }, intel, testHooks: true });
26	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
27	  endpoint = `http://127.0.0.1:${server.port}`;
28	});
29	
30	afterAll(async () => {
31	  await server.close();
32	});
33	
34	const seat = (index: number): Seat => ({ tileX: HUB_X - 8 + index * 4, tileY: OPEN_ROW, heading: EAST });
35	const config = createIntelConfig({ preset: "slice", finalIsland: { x: 0, y: 0 }, map: seaMap });
36	type Sighting = Extract<JournalMessage, { kind: "carrier-sighting" }>;
37	const sightingsOf = (client: HeadlessClient) => client.leads.filter((lead): lead is Sighting => lead.kind === "carrier-sighting");
38	
39	describe("carrier sightings (§3, §11)", () => {
40	  it("points a player at a carrier's sector as it was an interval before, when every copy of the type it lacks is carried: at most one sighting per snapshot, and free from the carrier reveal on", async ({ onTestFinished }) => {
41	    const track = tracker(onTestFinished);
